import * as T from './vendor/three.js';
export function createTunnels(scene,map,rawGround){
 const source=map.elements.find(e=>e.tags.name==='Wainuiomata Tunnel'&&e.tags.tunnel==='yes');if(!source)return null;
 const a=source.geometry[0],b=source.geometry.at(-1),dx=b.x-a.x,dz=b.z-a.z,length=Math.hypot(dx,dz),ux=dx/length,uz=dz/length,nx=uz,nz=-ux,width=3.5,wallHeight=2.7,radius=3.5,fa=rawGround(a.x,a.z)+.08,fb=rawGround(b.x,b.z)+.08;
 function floor(s){if(s<0){const d=Math.max(-18,s),h=rawGround(a.x-ux*18,a.z-uz*18);return T.MathUtils.lerp(h,fa,(d+18)/18)}if(s>length){const d=Math.min(18,s-length),h=rawGround(b.x+ux*18,b.z+uz*18);return T.MathUtils.lerp(fb,h,d/18)}return T.MathUtils.lerp(fa,fb,s/length)}
 function project(x,z){return{s:(x-a.x)*ux+(z-a.z)*uz,side:(x-a.x)*nx+(z-a.z)*nz}}
 function at(x,z,y){const p=project(x,z);if(p.s<-18||p.s>length+18||Math.abs(p.side)>width-.25)return null;const h=floor(p.s);if(y!==undefined&&(y<h-1||y>h+wallHeight+Math.sqrt(Math.max(0,radius*radius-p.side*p.side))-.3))return null;return{...p,floor:h}}
 const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const c=canvas.getContext('2d');c.fillStyle='#636a6b';c.fillRect(0,0,256,256);for(let y=0;y<256;y+=32)for(let x=-32;x<256;x+=64){const ox=x+(y/32%2)*32;c.fillStyle=['#626a6d','#727a7a','#596267'][(x+y+256)%3];c.fillRect(ox+1,y+1,62,30)}for(let i=0;i<2000;i++){c.fillStyle=i%2?'#ffffff10':'#06101b20';c.fillRect((i*73)%256,(i*43)%256,2,1)}const texture=new T.CanvasTexture(canvas);texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.colorSpace=T.SRGBColorSpace;texture.magFilter=T.NearestFilter;
 const shell=[],uvs=[],floorPoints=[],floorUV=[],profile=[[-width,0],[-width,wallHeight]];for(let j=1;j<=12;j++){const angle=Math.PI-j/12*Math.PI;profile.push([Math.cos(angle)*radius,wallHeight+Math.sin(angle)*radius])}profile.push([width,0]);
 const sections=Math.ceil(length/6);for(let i=0;i<sections;i++){const s0=i/sections*length,s1=(i+1)/sections*length;for(let j=0;j<profile.length-1;j++){const verts=[];for(const[s,p]of [[s0,profile[j]],[s1,profile[j]],[s1,profile[j+1]],[s0,profile[j+1]]])verts.push([a.x+ux*s+nx*p[0],floor(s)+p[1],a.z+uz*s+nz*p[0]]);for(const k of [0,1,2,0,2,3]){shell.push(...verts[k]);uvs.push((k===0||k===3?s0:s1)/7,(j+(k>1?1:0))/3)}}}
 for(let i=-3;i<sections+3;i++){const s0=Math.max(-18,i/sections*length),s1=Math.min(length+18,(i+1)/sections*length),v=[];for(const[s,side]of [[s0,-width],[s0,width],[s1,width],[s1,-width]])v.push([a.x+ux*s+nx*side,floor(s)+.025,a.z+uz*s+nz*side]);for(const k of [0,2,1,0,3,2]){floorPoints.push(...v[k]);floorUV.push(k===0||k===3?0:1,(k<2?s0:s1)/8)}}
 const geometry=(p,uv)=>{const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));if(uv)g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.computeVertexNormals();return g};const shellMesh=new T.Mesh(geometry(shell,uvs),new T.MeshBasicMaterial({map:texture,color:'#6b7279',side:T.DoubleSide}));scene.add(shellMesh);const floorMesh=new T.Mesh(geometry(floorPoints,floorUV),new T.MeshBasicMaterial({map:texture,color:'#4b545d',side:T.DoubleSide}));scene.add(floorMesh);
 const portalMaterial=new T.MeshLambertMaterial({color:'#a5adae',side:T.DoubleSide});const lightMaterial=new T.MeshBasicMaterial({color:'#fff0bf',toneMapped:false});
 const ribPoints=[];const beam=(p,q,w,h)=>{const g=new T.BoxGeometry(w,h,p.distanceTo(q)),matrix=new T.Matrix4().lookAt(p,q,new T.Vector3(0,1,0));matrix.setPosition(p.clone().add(q).multiplyScalar(.5));g.applyMatrix4(matrix);const non=g.toNonIndexed();ribPoints.push(...non.attributes.position.array);g.dispose();non.dispose()};
 for(let i=0;i<=length;i+=28){const x=a.x+ux*i,z=a.z+uz*i,y=floor(i)+wallHeight+radius-.4;const lamp=new T.Mesh(new T.BoxGeometry(1.2,.12,1.1),lightMaterial);lamp.position.set(x,y,z);scene.add(lamp);const ring=[];for(let j=0;j<=12;j++){const t=Math.PI-j/12*Math.PI;ring.push(new T.Vector3(x+nx*Math.cos(t)*3.42,floor(i)+wallHeight+Math.sin(t)*3.42,z+nz*Math.cos(t)*3.42))}for(let j=1;j<ring.length;j++)beam(ring[j-1],ring[j],.1,.12)}
 scene.add(new T.Mesh(geometry(ribPoints),new T.MeshBasicMaterial({color:'#3b494f'})));
 function portal(s,signDirection){const origin=new T.Vector3(a.x+ux*s,floor(s),a.z+uz*s),points=[];for(let j=0;j<12;j++){const t0=Math.PI-j/12*Math.PI,t1=Math.PI-(j+1)/12*Math.PI;const verts=[];for(const[r,t]of [[3.5,t0],[4.3,t0],[4.3,t1],[3.5,t1]])verts.push([origin.x+nx*Math.cos(t)*r,origin.y+wallHeight+Math.sin(t)*r,origin.z+nz*Math.cos(t)*r]);for(const k of [0,1,2,0,2,3])points.push(...verts[k])}scene.add(new T.Mesh(geometry(points),portalMaterial));for(const side of [-1,1]){const m=new T.Mesh(new T.BoxGeometry(.8,wallHeight,1),portalMaterial);m.position.set(origin.x+nx*side*3.9,origin.y+wallHeight/2,origin.z+nz*side*3.9);m.rotation.y=Math.atan2(nx,nz);scene.add(m)}const cv=document.createElement('canvas');cv.width=512;cv.height=96;const cx=cv.getContext('2d');cx.fillStyle='#244d43';cx.fillRect(0,0,512,96);cx.fillStyle='#e7edcb';cx.font='bold 27px monospace';cx.textAlign='center';cx.fillText('WAINUIOMATA TUNNEL',256,41);cx.font='13px monospace';cx.fillText('DISUSED ROUTE · FICTIONAL GAME INTERIOR',256,71);const tex=new T.CanvasTexture(cv);tex.colorSpace=T.SRGBColorSpace;tex.magFilter=T.NearestFilter;const sign=new T.Mesh(new T.PlaneGeometry(8,1.5),new T.MeshBasicMaterial({map:tex,side:T.DoubleSide}));sign.position.set(origin.x-ux*signDirection*.65,origin.y+7.5,origin.z-uz*signDirection*.65);sign.rotation.y=Math.atan2(-ux*signDirection,-uz*signDirection);scene.add(sign)}portal(0,1);portal(length,-1);
 const portalUniforms={tunnelA:{value:new T.Vector3(a.x,fa,a.z)},tunnelB:{value:new T.Vector3(b.x,fb,b.z)},tunnelAxis:{value:new T.Vector2(ux,uz)}};
 function applyTerrain(material){material.onBeforeCompile=shader=>{Object.assign(shader.uniforms,portalUniforms);shader.vertexShader='varying vec3 tunnelWorldPosition;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\ntunnelWorldPosition=(modelMatrix*vec4(position,1.0)).xyz;');shader.fragmentShader='varying vec3 tunnelWorldPosition;uniform vec3 tunnelA;uniform vec3 tunnelB;uniform vec2 tunnelAxis;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <clipping_planes_fragment>',`#include <clipping_planes_fragment>
 vec2 relA=tunnelWorldPosition.xz-tunnelA.xz;vec2 relB=tunnelWorldPosition.xz-tunnelB.xz;float sideA=abs(dot(relA,vec2(tunnelAxis.y,-tunnelAxis.x)));float sideB=abs(dot(relB,vec2(tunnelAxis.y,-tunnelAxis.x)));float alongA=dot(relA,tunnelAxis);float alongB=-dot(relB,tunnelAxis);float ceilA=tunnelA.y+2.7+sqrt(max(0.,12.25-sideA*sideA));float ceilB=tunnelB.y+2.7+sqrt(max(0.,12.25-sideB*sideB));if((sideA<3.5&&alongA>-18.&&alongA<32.&&tunnelWorldPosition.y<ceilA)||(sideB<3.5&&alongB>-18.&&alongB<32.&&tunnelWorldPosition.y<ceilB))discard;
`)};material.customProgramCacheKey=()=> 'terrain-tunnel-portals-v1';material.needsUpdate=true}
 const entrances=[{name:'Tunnel · Wainuiomata portal',x:a.x-ux*12,z:a.z-uz*12,s:-12,yaw:Math.atan2(-ux,-uz)},{name:'Tunnel · Hutt portal',x:b.x+ux*12,z:b.z+uz*12,s:length+12,yaw:Math.atan2(ux,uz)}];
 return{length,entrances,at,project,floor,applyTerrain,clearPortal(x,z){const p=project(x,z);return Math.abs(p.side)<9&&(Math.abs(p.s)<30||Math.abs(p.s-length)<30)},canMove(x,z,y,from){const current=at(from.x,from.z,y);if(!current||current.s<0||current.s>length)return true;const p=project(x,z);return p.s<0||p.s>length||Math.abs(p.side)<width-.4},walkHeight(x,z,y){const p=at(x,z,y);return p?p.floor:null}};
}
